// ============================================================
// The Worker entry point (wrangler.jsonc `main`).
//
// OpenNext generates `.open-next/worker.js` with only a `fetch` handler, so this
// thin wrapper adds the `scheduled` handler Cloudflare Cron Triggers need and
// otherwise passes everything through unchanged. Same pattern as any Worker that
// exports `{ fetch, scheduled }`.
// ============================================================

/* eslint-disable @typescript-eslint/ban-ts-comment */
// @ts-ignore: generated by `opennextjs-cloudflare build`, absent at type-check time
import handler from '../.open-next/worker.js'
import { runScheduled, type CronEnv } from '../src/lib/cron/run'
import { isChatSocketRequest, routeChatSocket, type ChatSocketEnv } from '../src/lib/chat/socket-route'

export default {
  // Live-chat WebSockets go straight to the ChatRoom Durable Object; everything else is Next.
  fetch(request: Request, env: ChatSocketEnv, ctx: unknown) {
    if (isChatSocketRequest(request)) return routeChatSocket(request, env)
    return (handler as { fetch: (...args: unknown[]) => unknown }).fetch(request, env, ctx)
  },
  async scheduled(_event: unknown, env: CronEnv, ctx: { waitUntil(p: Promise<unknown>): void }) {
    ctx.waitUntil(runScheduled(env))
  },
}

// The generated worker's Durable Object classes must stay exported from the entry point.
// @ts-ignore
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from '../.open-next/worker.js'

// Live chat: one room per conversation (binding CHAT_ROOM in wrangler.jsonc).
export { ChatRoom } from './chat-room'
